#!/usr/bin/env python3
"""Lints commit message against conventional commit format."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from tools.pr_governance_core.common import CONVENTIONAL_COMMIT_RE


def lint_commit_msg(msg: str) -> bool:
    first_line = msg.strip().splitlines()[0] if msg.strip() else ""
    if not first_line:
        return False
    # Allow merge commit messages generated by git / PR governance
    if first_line.startswith("Merge branch '") or first_line.startswith("Merge pull request #"):
        return True
    return bool(CONVENTIONAL_COMMIT_RE.match(first_line))


def main() -> int:
    parser = argparse.ArgumentParser(description="Lint commit message.")
    parser.add_argument("-f", "--file", required=True, help="Path to commit message file")
    args = parser.parse_args()

    msg_file = Path(args.file)
    if not msg_file.is_file():
        print(f"Error: Commit message file '{args.file}' not found.", file=sys.stderr)
        return 1

    content = msg_file.read_text(encoding="utf-8", errors="replace")
    if not lint_commit_msg(content):
        first_line = content.strip().splitlines()[0] if content.strip() else ""
        print(f"❌ COMMIT MESSAGE REJECTED: '{first_line}' does not follow conventional commit format.", file=sys.stderr)
        print("   Allowed formats: feat(...): ..., fix(...): ..., chore(...): ..., docs(...): ..., refactor(...): ..., test(...): ..., ci(...): ...", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
